#!/usr/bin/env bash
# ZONO — apply "הנכסים שלי" (server-paginated command table) + ZI grid-column fix.
# Realigns to origin/main, applies 2 commits, pushes. macOS-safe base64 decode.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git am --abort 2>/dev/null || true
git fetch origin
git checkout main
git reset --hard origin/main
cat > /tmp/zono-props.patch.b64 <<'B64EOF'

B64EOF
# macOS/BSD base64 wants stdin (positional file arg is a GNU-only extension).
base64 -d < /tmp/zono-props.patch.b64 > /tmp/zono-props.patch
git am /tmp/zono-props.patch
echo "→ commits applied:"; git log --oneline -3
git push origin main
echo "✓ pushed. Redeploy will pick up /my-properties."
